#!/usr/bin/env node
'use strict';

/**
 * Wispy Finance Writer — Production Ambbi / Metropolitan burn ledger.
 *
 * Production defaults:
 *   GSHEET_ID: 1htz5jbM26ZnjTCC7rl43g46pPhjDoVjUAlmwMaDfGoE
 *   GSHEET_TAB: Burn ambbi
 *   DRIVE_ROOT_ID: 1cD4Vs5UbZTlKpGhvYEHRveqfqYJ7jUTb
 *
 * Input: JSON generated by WhatsApp/audio CFO parser via --json, --file, or stdin.
 * Optional receipt upload: pass comprobantePath / receiptPath / attachmentPath in JSON.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const DEFAULT_CREDENTIALS = '/home/franco/.openclaw/workspace/secrets/google-sa-credentials.json';
const DEFAULT_SPREADSHEET_ID = '1htz5jbM26ZnjTCC7rl43g46pPhjDoVjUAlmwMaDfGoE';
const DEFAULT_SHEET_NAME = 'Burn ambbi';
const DEFAULT_DRIVE_ROOT_ID = '1cD4Vs5UbZTlKpGhvYEHRveqfqYJ7jUTb';
const TOKEN_URL = 'https://oauth2.googleapis.com/token';
const SHEETS_BASE = 'https://sheets.googleapis.com/v4/spreadsheets';
const DRIVE_BASE = 'https://www.googleapis.com/drive/v3';
const DRIVE_UPLOAD_BASE = 'https://www.googleapis.com/upload/drive/v3';
const SCOPES = [
  'https://www.googleapis.com/auth/spreadsheets',
  'https://www.googleapis.com/auth/drive'
];

const MONTHS_ES = [
  'ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO',
  'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'
];

const REQUIRED_BURN_COLUMNS = [
  'ESTADO', 'COST CENTER', 'AÑO', 'N° MES', 'MES', 'CATEGORIA', 'EMPRESA', 'DEPTO',
  'DESCRIPCION', 'CANTIDAD', 'EGRESO', 'MEDIO DE PAGO', 'PRECIO UNITARIO', 'PESOS',
  'USD', 'TIPO DE CAMBIO', 'FECHA DE PAGO', 'CUOTAS', 'ANOTACIONES', 'COMPROBANTE (LINK)',
  'FUENTE DEL DATO', 'NOTAS DEL SISTEMA'
];

const VENDOR_NORMALIZATION = new Map([
  ['gustavo torres', 'Gustavo J. Torres'],
  ['gustavo j torres', 'Gustavo J. Torres'],
  ['gustavo j. torres', 'Gustavo J. Torres'],
  ['lewy', 'Lewi'],
  ['lewi', 'Lewi'],
  ['cantor', 'Kantor'],
  ['kantor', 'Kantor']
]);

function usage() {
  console.log(`Usage:
  node scripts/wispy-finance-writer.js --print-email
  node scripts/wispy-finance-writer.js --dry-run --json '{"empresa":"Ambbi","descripcion":"Arreglo eléctrico","pesos":50000,"proveedor":"Gustavo Torres"}'
  node scripts/wispy-finance-writer.js --file expense.json
  cat expense.json | node scripts/wispy-finance-writer.js

Env overrides:
  GOOGLE_APPLICATION_CREDENTIALS=${DEFAULT_CREDENTIALS}
  WISPY_FINANCE_SPREADSHEET_ID=${DEFAULT_SPREADSHEET_ID}
  WISPY_FINANCE_SHEET_NAME=${DEFAULT_SHEET_NAME}
  WISPY_FINANCE_DRIVE_ROOT_ID=${DEFAULT_DRIVE_ROOT_ID}`);
}

function parseArgs(argv) {
  const args = { dryRun: false, printEmail: false, json: null, file: null, help: false };
  for (let i = 2; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--dry-run') args.dryRun = true;
    else if (arg === '--print-email') args.printEmail = true;
    else if (arg === '--help' || arg === '-h') args.help = true;
    else if (arg === '--json') args.json = argv[++i];
    else if (arg === '--file') args.file = argv[++i];
    else throw new Error(`Unknown argument: ${arg}`);
  }
  return args;
}

function readCredentials() {
  const credentialsPath = process.env.GOOGLE_APPLICATION_CREDENTIALS || DEFAULT_CREDENTIALS;
  const credentials = JSON.parse(fs.readFileSync(credentialsPath, 'utf8'));
  if (credentials.type !== 'service_account' || !credentials.client_email || !credentials.private_key) {
    throw new Error(`Invalid service account credentials at ${credentialsPath}`);
  }
  return { credentials, credentialsPath };
}

function base64url(input) {
  return Buffer.from(input).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function signJwt(credentials) {
  const now = Math.floor(Date.now() / 1000);
  const unsigned = `${base64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }))}.${base64url(JSON.stringify({
    iss: credentials.client_email,
    scope: SCOPES.join(' '),
    aud: TOKEN_URL,
    exp: now + 3600,
    iat: now
  }))}`;
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(unsigned);
  signer.end();
  const signature = signer.sign(credentials.private_key, 'base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
  return `${unsigned}.${signature}`;
}

async function getAccessToken(credentials) {
  const response = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
      assertion: signJwt(credentials)
    })
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(`Google token error ${response.status}: ${JSON.stringify(payload)}`);
  return payload.access_token;
}

function sheetRange(sheetName, range) {
  return `'${String(sheetName).replace(/'/g, "''")}'!${range}`;
}

async function googleJson(url, { token, method = 'GET', body, headers = {} } = {}) {
  const response = await fetch(url, {
    method,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', ...headers },
    body: body ? JSON.stringify(body) : undefined
  });
  const text = await response.text();
  const payload = text ? JSON.parse(text) : null;
  if (!response.ok) throw new Error(`Google API ${method} ${url} failed ${response.status}: ${text}`);
  return payload;
}

async function getHeader({ token, spreadsheetId, sheetName }) {
  const range = encodeURIComponent(sheetRange(sheetName, '1:1'));
  const payload = await googleJson(`${SHEETS_BASE}/${spreadsheetId}/values/${range}`, { token });
  const header = payload.values?.[0] || [];
  const missing = REQUIRED_BURN_COLUMNS.filter((col) => !header.includes(col));
  if (missing.length) throw new Error(`Ledger header missing required columns: ${missing.join(', ')}`);
  return header;
}

async function appendRow({ token, spreadsheetId, sheetName, row }) {
  const range = encodeURIComponent(sheetRange(sheetName, 'A:AC'));
  return googleJson(`${SHEETS_BASE}/${spreadsheetId}/values/${range}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`, {
    token,
    method: 'POST',
    body: { values: [row] }
  });
}

function pick(input, keys, fallback = '') {
  for (const key of keys) {
    if (input[key] !== undefined && input[key] !== null && input[key] !== '') return input[key];
  }
  return fallback;
}

function normalizeMoney(value) {
  if (value === undefined || value === null || value === '') return '';
  if (typeof value === 'number') return value;
  const raw = String(value).trim();
  if (!raw) return '';
  const decimalComma = raw.includes(',') && (!raw.includes('.') || raw.lastIndexOf(',') > raw.lastIndexOf('.'));
  const cleaned = decimalComma
    ? raw.replace(/\./g, '').replace(',', '.').replace(/[^0-9.-]/g, '')
    : raw.replace(/,/g, '').replace(/[^0-9.-]/g, '');
  return cleaned === '' ? '' : Number(cleaned);
}

function parseDate(inputDate) {
  if (!inputDate) return new Date();
  if (inputDate instanceof Date) return inputDate;
  const raw = String(inputDate).trim();
  const dmY = raw.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);
  if (dmY) {
    const [, d, m, y] = dmY;
    return new Date(Number(y.length === 2 ? `20${y}` : y), Number(m) - 1, Number(d));
  }
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? new Date() : parsed;
}

function formatDate(date) {
  const d = String(date.getDate()).padStart(2, '0');
  const m = String(date.getMonth() + 1).padStart(2, '0');
  return `${d}/${m}/${date.getFullYear()}`;
}

function monthFolderName(date) {
  return `${String(date.getMonth() + 1).padStart(2, '0')} - ${MONTHS_ES[date.getMonth()][0]}${MONTHS_ES[date.getMonth()].slice(1).toLowerCase()}`;
}

function safeName(value) {
  return String(value || 'Sin proveedor').replace(/[\\/:*?"<>|]/g, '-').replace(/\s+/g, ' ').trim().slice(0, 120);
}

function normalizeCompany(value) {
  const raw = String(value || 'Ambbi').trim().toLowerCase();
  if (raw.includes('metro')) return 'Metropolitan';
  if (raw.includes('canarian')) throw new Error('Scope rechazado: CANARIAN no se registra en este ledger de Ambbi/Metropolitan.');
  if (raw.includes('personal')) throw new Error('Scope rechazado: gasto personal fuera del canal Ambbi/Metropolitan.');
  return 'Ambbi';
}

function normalizeVendor(value) {
  const raw = String(value || '').trim();
  const key = raw.toLowerCase().replace(/\./g, '').replace(/\s+/g, ' ');
  return VENDOR_NORMALIZATION.get(key) || raw;
}

async function fetchBlueRate() {
  const response = await fetch('https://dolarapi.com/v1/dolares/blue', { headers: { Accept: 'application/json' } });
  if (!response.ok) throw new Error(`dolarapi blue HTTP ${response.status}`);
  const payload = await response.json();
  const venta = Number(payload.venta);
  if (!Number.isFinite(venta) || venta <= 0) throw new Error(`dolarapi venta inválida: ${JSON.stringify(payload)}`);
  return { venta, payload };
}

async function findOrCreateFolder({ token, parentId, name }) {
  const q = [
    `mimeType='application/vnd.google-apps.folder'`,
    `name='${String(name).replace(/'/g, "\\'")}'`,
    `'${parentId}' in parents`,
    'trashed=false'
  ].join(' and ');
  const search = await googleJson(`${DRIVE_BASE}/files?q=${encodeURIComponent(q)}&fields=files(id,name,webViewLink)&supportsAllDrives=true&includeItemsFromAllDrives=true`, { token });
  if (search.files?.[0]) return search.files[0];
  return googleJson(`${DRIVE_BASE}/files?fields=id,name,webViewLink&supportsAllDrives=true`, {
    token,
    method: 'POST',
    body: { name, mimeType: 'application/vnd.google-apps.folder', parents: [parentId] }
  });
}

function detectMime(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '.pdf') return 'application/pdf';
  if (ext === '.png') return 'image/png';
  if (ext === '.jpg' || ext === '.jpeg') return 'image/jpeg';
  if (ext === '.webp') return 'image/webp';
  return 'application/octet-stream';
}

async function uploadReceipt({ token, rootId, filePath, date, provider, amount }) {
  if (!filePath) return '';
  if (!fs.existsSync(filePath)) throw new Error(`Comprobante no encontrado: ${filePath}`);
  const yearFolder = await findOrCreateFolder({ token, parentId: rootId, name: String(date.getFullYear()) });
  const monthFolder = await findOrCreateFolder({ token, parentId: yearFolder.id, name: monthFolderName(date) });
  const ext = path.extname(filePath) || '';
  const filename = `${date.toISOString().slice(0, 10)} - ${safeName(provider)} - ${safeName(amount)}${ext}`;
  const boundary = `wispy_${crypto.randomBytes(12).toString('hex')}`;
  const metadata = { name: filename, parents: [monthFolder.id] };
  const file = fs.readFileSync(filePath);
  const body = Buffer.concat([
    Buffer.from(`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n`),
    Buffer.from(`--${boundary}\r\nContent-Type: ${detectMime(filePath)}\r\n\r\n`),
    file,
    Buffer.from(`\r\n--${boundary}--\r\n`)
  ]);
  const response = await fetch(`${DRIVE_UPLOAD_BASE}/files?uploadType=multipart&fields=id,name,webViewLink&supportsAllDrives=true`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': `multipart/related; boundary=${boundary}` },
    body
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(`Drive upload failed ${response.status}: ${JSON.stringify(payload)}`);
  return payload.webViewLink || `https://drive.google.com/file/d/${payload.id}/view`;
}

function setByHeader(row, header, column, value) {
  const index = header.indexOf(column);
  if (index >= 0) row[index] = value;
}

async function buildLedgerRow(input, header, { token, driveRootId }) {
  const paymentDate = parseDate(pick(input, ['FECHA DE PAGO', 'fecha_de_pago', 'fecha_pago', 'fecha'], null));
  const company = normalizeCompany(pick(input, ['EMPRESA', 'empresa'], 'Ambbi'));
  const provider = normalizeVendor(pick(input, ['PROVEEDOR', 'proveedor', 'vendor'], ''));
  const currency = String(pick(input, ['moneda', 'moneda_original', 'currency'], '')).toUpperCase();
  const rawAmount = normalizeMoney(pick(input, ['monto', 'monto_original', 'amount', 'EGRESO', 'egreso'], ''));
  let pesos = normalizeMoney(pick(input, ['PESOS', 'pesos', 'ars'], currency === 'ARS' ? rawAmount : ''));
  let usd = normalizeMoney(pick(input, ['USD', 'usd'], currency === 'USD' ? rawAmount : ''));
  let fx = normalizeMoney(pick(input, ['TIPO DE CAMBIO', 'tipo_de_cambio', 'fx', 'tc'], ''));
  let fxNote = '';

  if (pesos && !usd) {
    if (!fx) {
      const blue = await fetchBlueRate();
      fx = blue.venta;
      fxNote = `TC blue venta dolarapi ${fx}`;
    }
    usd = Number((pesos / fx).toFixed(2));
  }
  if (usd && !pesos && fx) pesos = Number((usd * fx).toFixed(2));

  const receiptPath = pick(input, ['comprobantePath', 'receiptPath', 'attachmentPath', 'filePath'], '');
  const receiptLink = receiptPath
    ? await uploadReceipt({ token, rootId: driveRootId, filePath: receiptPath, date: paymentDate, provider, amount: pesos || usd || rawAmount })
    : pick(input, ['COMPROBANTE (LINK)', 'comprobante', 'comprobante_link', 'receiptUrl'], '');

  const quantity = pick(input, ['CANTIDAD', 'cantidad'], 1);
  const category = pick(input, ['CATEGORIA', 'categoria'], 'REVISAR');
  const costCenter = pick(input, ['COST CENTER', 'cost_center', 'unidad', 'propiedad'], company === 'Ambbi' ? 'Ambbi General' : 'Metropolitan General');
  const description = pick(input, ['DESCRIPCION', 'descripcion', 'concepto', 'description'], provider ? `Pago ${provider}` : 'Gasto cargado por Wispy');
  const notes = [
    pick(input, ['NOTAS CFO', 'notas_cfo', 'notas', 'notes'], ''),
    fxNote,
    `confianza=${pick(input, ['CONFIANZA', 'confianza', 'confidence'], 'media')}`
  ].filter(Boolean).join(' | ');

  const row = Array(header.length).fill('');
  setByHeader(row, header, 'ESTADO', pick(input, ['ESTADO', 'estado'], 'pagado'));
  setByHeader(row, header, 'COST CENTER', costCenter);
  setByHeader(row, header, 'AÑO', paymentDate.getFullYear());
  setByHeader(row, header, 'N° MES', paymentDate.getMonth() + 1);
  setByHeader(row, header, 'MES', MONTHS_ES[paymentDate.getMonth()]);
  setByHeader(row, header, 'CATEGORIA', category);
  setByHeader(row, header, 'EMPRESA', company);
  setByHeader(row, header, 'DEPTO', pick(input, ['DEPTO', 'depto', 'departamento'], ''));
  setByHeader(row, header, 'DESCRIPCION', description);
  setByHeader(row, header, 'CANTIDAD', quantity);
  setByHeader(row, header, 'EGRESO', pick(input, ['EGRESO', 'egreso', 'tipo_egreso'], category));
  setByHeader(row, header, 'MEDIO DE PAGO', pick(input, ['MEDIO DE PAGO', 'medio_de_pago', 'payment_method'], ''));
  setByHeader(row, header, 'PRECIO UNITARIO', pick(input, ['PRECIO UNITARIO', 'precio_unitario'], rawAmount || pesos || usd));
  setByHeader(row, header, 'PESOS', pesos || '');
  setByHeader(row, header, 'USD', usd || '');
  setByHeader(row, header, 'TIPO DE CAMBIO', fx || '');
  setByHeader(row, header, 'FECHA DE PAGO', formatDate(paymentDate));
  setByHeader(row, header, 'CUOTAS', pick(input, ['CUOTAS', 'cuotas'], ''));
  setByHeader(row, header, 'ANOTACIONES', provider ? `Proveedor: ${provider}` : '');
  setByHeader(row, header, 'COMPROBANTE (LINK)', receiptLink);
  setByHeader(row, header, 'FUENTE DEL DATO', pick(input, ['FUENTE', 'fuente', 'source'], 'WhatsApp'));
  setByHeader(row, header, 'NOTAS DEL SISTEMA', notes || 'Cargado por Wispy CFO');
  return { row, computed: { company, provider, pesos, usd, fx, receiptLink, paymentDate: formatDate(paymentDate), month: MONTHS_ES[paymentDate.getMonth()] } };
}

async function readInput(args) {
  if (args.json) return JSON.parse(args.json);
  if (args.file) return JSON.parse(fs.readFileSync(args.file, 'utf8'));
  if (!process.stdin.isTTY) {
    const chunks = [];
    for await (const chunk of process.stdin) chunks.push(chunk);
    const raw = Buffer.concat(chunks).toString('utf8').trim();
    if (raw) return JSON.parse(raw);
  }
  throw new Error('Missing input JSON. Use --json, --file, or stdin.');
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) return usage();
  const { credentials, credentialsPath } = readCredentials();
  if (args.printEmail) {
    console.log(JSON.stringify({
      serviceAccountEmail: credentials.client_email,
      projectId: credentials.project_id,
      credentialsPath,
      spreadsheetId: process.env.WISPY_FINANCE_SPREADSHEET_ID || DEFAULT_SPREADSHEET_ID,
      sheetName: process.env.WISPY_FINANCE_SHEET_NAME || DEFAULT_SHEET_NAME,
      driveRootId: process.env.WISPY_FINANCE_DRIVE_ROOT_ID || DEFAULT_DRIVE_ROOT_ID
    }, null, 2));
    return;
  }

  const input = await readInput(args);
  const spreadsheetId = process.env.WISPY_FINANCE_SPREADSHEET_ID || input.spreadsheetId || DEFAULT_SPREADSHEET_ID;
  const sheetName = process.env.WISPY_FINANCE_SHEET_NAME || input.sheetName || DEFAULT_SHEET_NAME;
  const driveRootId = process.env.WISPY_FINANCE_DRIVE_ROOT_ID || input.driveRootId || DEFAULT_DRIVE_ROOT_ID;
  const token = await getAccessToken(credentials);
  const header = await getHeader({ token, spreadsheetId, sheetName });
  const { row, computed } = await buildLedgerRow(input, header, { token, driveRootId });

  if (args.dryRun) {
    console.log(JSON.stringify({ dryRun: true, spreadsheetId, sheetName, driveRootId, header, row, computed }, null, 2));
    return;
  }

  const append = await appendRow({ token, spreadsheetId, sheetName, row });
  console.log(JSON.stringify({ ok: true, spreadsheetId, sheetName, computed, append: append.updates || append }, null, 2));
}

main().catch((error) => {
  console.error(JSON.stringify({ ok: false, error: error.message }, null, 2));
  process.exit(1);
});
